def gen(rng):
    def rs(n):
        s = [rng.choice('xyz')]
        for _ in range(n - 1):
            s.append(rng.choice([c for c in 'xyz' if c != s[-1]]))
        return ''.join(s)

    def cyc(n, order, start):
        return ''.join(order[(start + i) % 3] for i in range(n))

    def fmt(a, b):
        return a + '\n' + b

    tests = [fmt('x', 'y'), fmt('x', 'x'), fmt('z', 'x'), fmt('xy', 'yx'), fmt('xy', 'xy'), fmt('xz', 'zx'),
             fmt('zxyz', 'zyxz'), fmt('xyz', 'zyx'), fmt('xyx', 'zyz'), fmt('xyxy', 'yxyx')]
    for n in range(1, 9):
        for _ in range(3):
            tests.append(fmt(rs(n), rs(n)))
    for _ in range(12):
        n = rng.randint(2, 8)
        tests.append(fmt(rs(n), rs(n)))
    tests.append(fmt('xyzyzyxyzx', 'xzyzyzyxzy'))
    tests.append(fmt('xyxyxyxyxy', 'xzyxyxzyxz'))
    tests.append(fmt('xyxyzyzyxy', 'zyzyxzyzyz'))
    tests.append(fmt('xzxyxyzyzyxyzx', 'zyzyxzyzyzyxzy'))
    n = 100000
    tests.append(fmt(rs(n), rs(n)))
    tests.append(fmt(cyc(n, 'xyz', 0), cyc(n, 'zyx', 0)))
    tests.append(fmt(cyc(n, 'xyz', 0), cyc(n, 'zyx', 1)))
    tests.append(fmt(cyc(n, 'xyz', 1), cyc(n, 'xyz', 0)))
    tests.append(fmt(('xy' * n)[:n], ('yx' * n)[:n]))
    tests.append(fmt(rs(20000), rs(20000)))
    return tests
